def find_components(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    components = []

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and (i, j) not in visited:
                comp = []
                stack = [(i, j)]
                while stack:
                    r, c = stack.pop()
                    if (r, c) in visited:
                        continue
                    visited.add((r, c))
                    comp.append((r, c))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 1 and (nr, nc) not in visited:
                                stack.append((nr, nc))
                components.append((list(comp), comp))  # (cells, canonical form)
    # Sort by size descending
    components.sort(key=lambda x: x[0], reverse=True)
    return components

